lookup = {}

def makeMove(gamestring, location):
	if gamestring[location] == "0":
		return gamestring[:location] + "1" + gamestring[location + 1:]
	leftreplace = -1
	rightreplace = -1
	for i in range(location - 1, -1, -1):
		if gamestring[i] == "0":
			leftreplace = i
			break
	for i in range(location + 1, len(gamestring)):
		if gamestring[i] == "0":
			rightreplace = i
			break
	leftpiece = ""
	rightpiece = ""
	if leftreplace == -1:
		leftpiece = gamestring[:location]
	else:
		leftpiece = gamestring[:leftreplace] + "1" + gamestring[leftreplace + 1:location]
	if rightreplace == -1:
		rightpiece = gamestring[location + 1:]
	else:
		rightpiece = gamestring[location + 1:rightreplace] + "1" + gamestring[rightreplace + 1:]
	return leftpiece + "0" + rightpiece

def findWinner(turn, gamestring):
	if(str(turn)+gamestring in lookup.keys()):
		return lookup[str(turn)+gamestring]
	if gamestring.count("0") == 1:
		lookup[str(turn)+gamestring]=turn
		return turn
	for i in range(0, len(gamestring)):
		newstring = makeMove(gamestring, i)
		if findWinner(0-turn, newstring)==turn:
			lookup[str(turn)+gamestring]=turn
			return turn
	lookup[str(turn)+gamestring]=0-turn
	return 0-turn

