    &= \frac14\sqrt{-4(b^2+c^2-2a^2)^2-b^4-c^4+4(b^2+c^2)(b^2+c^2-2a^2) + 2b^2c^2}
    &= \frac14\sqrt{-16a^4-b^4-c^4+8a^2b^2+8a^2c^2+2b^2c^2}.
\end{align*}
