\begin{align*}
\frac{a_k}{p_k}=\frac{a_k}{(1+a_1)(1+a_2)\cdots (1+a_k)}&=\frac{a_k+1}{(1+a_1)(1+a_2)\cdots (1+a_k)}-\frac{1}{(1+a_1)(1+a_2)\cdots(1+a_k)}
&= \frac{1}{(1+a_1)(1+a_2)\cdots(1+a_{k-1})}-\frac{1}{(1+a_1)(1+a_2)\cdots(1+a_k)}
&= \frac{1}{p_{k-1}}-\frac{1}{p_k}.
\end{align*}
Thus,
\begin{align*}
S &= \sum_{i=1}^n \frac{a_i}{p_i}
&= \sum_{i=1}^n \left(\frac{1}{p_{i-1}}-\frac{1}{p_i}\right)
&= 1-\frac{1}{p_n}.
